import React, { useEffect, useState } from 'react';
import { defineMessages, useIntl } from 'react-intl';
import { useCustomerType, useShopperBasketsMutationHelper } from '@salesforce/commerce-sdk-react';
import Seo from '@salesforce/retail-react-app/app/components/seo';
import { Box, Button, Center, Heading, Stack, Text } from '@salesforce/retail-react-app/app/components/shared/ui';
import Link from '@salesforce/retail-react-app/app/components/link';
import useEinstein from '@salesforce/retail-react-app/app/hooks/use-einstein';
import { useToast } from '@salesforce/retail-react-app/app/hooks/use-toast';
import { API_ERROR_MESSAGE, EINSTEIN_RECOMMENDERS } from '@salesforce/retail-react-app/app/constants';
// Zimmermann's own constant — NOT the base package above (see recommended-products/index.tsx's
// own comment on this exact gotcha: a named import off the base package's untyped module compiles
// but is undefined at runtime). APP_MAIN_BLEED_MX, not PAGE_CONTENT_BLEED_MX — this page has no
// PageContainer/layerStyle second containment layer for PAGE_CONTENT_BLEED_MX to correctly
// cancel; see that constant's own comment in app/constants/index.ts for the bug this distinction
// fixes (a real, live-confirmed horizontal overflow, Marcel, 2026-09-10).
import { APP_MAIN_BLEED_MX } from 'app/constants';
import { ZimmRecentlyViewedGrid } from '../../components/ui-kits/organisms/zimmRecentlyViewedGrid';
import type { ZimmProductCardProps } from '../../components/ui-kits/organisms/zimmProductCard';
import {
  selectRecentlyViewedFullHistoryCard,
  resolveOrderableVariant,
} from '../../utils/recentlyViewedFullHistoryCard';
import type {
  RecentlyViewedFullHistoryCard,
  RecentlyViewedFullHistoryProduct,
} from '../../utils/recentlyViewedFullHistoryCard';

// Message-id namespace follows this codebase's existing `<page>.<category>.<key>` convention
// (see home.*, product_list.*, product_detail.* in their own index.tsx files) -- `recently_viewed`
// is this page's own snake_case prefix.
const messages = defineMessages({
  title: {
    id: 'recently_viewed.heading.title',
    defaultMessage: 'Recently Viewed',
  },
  // Real ICU `plural` selector, not string interpolation -- decided explicitly this session
  // (build plan §B1, "go for it" -- Marcel, 2026-09-08). `#` is replaced by the matched `count`
  // value at each branch, so this renders "1 item" / "16 items" correctly with no separate
  // singular-check needed at the call site. Lowercase "item(s)" -- corrected 2026-09-11 (Marcel).
  itemCount: {
    id: 'recently_viewed.label.item_count',
    defaultMessage: '{count, plural, one {# item} other {# items}}',
  },
  emptyHeading: {
    id: 'recently_viewed.empty.heading',
    defaultMessage: "You haven't viewed anything yet.",
  },
  emptyBodyRegistered: {
    id: 'recently_viewed.empty.body_registered',
    defaultMessage: 'Continue shopping to start building your history.',
  },
  emptyBodyGuest: {
    id: 'recently_viewed.empty.body_guest',
    defaultMessage: 'Sign in to keep track of your history, or continue shopping.',
  },
  continueShopping: {
    id: 'recently_viewed.empty.cta.continue_shopping',
    defaultMessage: 'Continue Shopping',
  },
  signIn: {
    id: 'recently_viewed.empty.cta.sign_in',
    defaultMessage: 'Sign In',
  },
  // Same copy, same event, as product-list/index.tsx's own `product_list.toast.added_to_bag` --
  // a distinct message id under this page's own `recently_viewed.*` namespace (see this file's own
  // message-id-namespace comment above) rather than importing that page's message across a page
  // boundary.
  addedToBag: {
    id: 'recently_viewed.toast.added_to_bag',
    defaultMessage: 'Added to bag',
  },
});

// Plain literal, not run through react-intl -- matches home/index.tsx's own un-translated Seo
// `description` precedent (`description="Commerce Cloud Retail React App"`). The build plan's
// SEO section only calls out `title` for useIntl; this page's own description copy was never
// specified, so it is authored here rather than invented as a translated message with no source.
const PAGE_DESCRIPTION = "Browse the products you've recently viewed at Zimmermann.";

type EmptyRecentlyViewedProps = {
  isRegistered: boolean;
};

/**
 * SFCC-84's own empty-state design (build plan §B2 "Empty state"). There is no AC or Figma design
 * for this state at all; copy and structure are ported from the real `EmptyCart` precedent
 * (`node_modules/@salesforce/retail-react-app/app/pages/cart/partials/empty-cart.jsx`), per
 * Marcel's own direction ("look for a pattern in the existing codebase and build off that"): a
 * `Box` > `Center` > `Stack` layout, an `isRegistered`-branched body message, and a
 * `Button as={Link}` CTA pattern (the base SFCC `Link`, not a raw `react-router-dom` one, so the
 * "Continue Shopping"/"Sign In" hrefs get this storefront's real multi-site URL prefixing --
 * `use-multi-site.js`'s `buildUrl`, called internally by that `Link` -- the same reason `EmptyCart`
 * itself uses it).
 *
 * **Deliberately not a byte-for-byte styling port.** `EmptyCart`'s own prop values
 * (`fontSize={['18px', '2xl']}`, `color="gray.700"`, `color="blue.600"`,
 * `width={['343px', '220px']}`) are raw base-Chakra literals with no relationship to Zimmermann's
 * design tokens, and this codebase's styling hierarchy
 * (`.claude/rules/overrideStyling.md`) requires `textStyle`/`var(--zimm-*)` for new
 * Zimmermann-authored UI and forbids a raw px/rem literal outright. With no confirmed empty-state
 * Figma spec to derive exact values from, this uses the nearest reasonable *registered* tokens
 * (`heading2`/`body1` text styles, `text-default`/`text-secondary` colours, `2xl`/`2xs`/`m`
 * spacing) instead -- an autonomous styling judgement call (see this module's own bottom-of-file
 * decision log), not a design decision that conflicts with an existing one (there is no existing
 * design here to conflict with).
 *
 * **No icon.** `EmptyCart` renders `BasketIcon` above its heading and `AccountIcon` on its
 * "Sign In" button. Checked directly against `overrides/app/components/icons`' full export list:
 * no Recently-Viewed-thematic icon exists (no eye/clock/history glyph), and forcing an unrelated
 * one -- `BasketIcon` itself, or reusing `AccountIcon` -- would misrepresent this page rather than
 * help it, so both are omitted; heading + copy + CTA(s) alone still satisfies the established
 * empty-state pattern this page is following.
 *
 * `useIntl` is called directly in this leaf, not passed down as a prop -- this is the
 * Context-backed, app-wide exception `.claude/rules/components.md` > Composition documents for
 * `useIntl`/`useUiCopy` specifically (this is a private, single-parent sub-component of this page,
 * not a component exported from its own folder, so it needs no story/test of its own either --
 * its behaviour is exercised through this page's own `index.test.tsx`).
 */
const EmptyRecentlyViewed = ({ isRegistered }: EmptyRecentlyViewedProps) => {
  const intl = useIntl();

  return (
    <Box data-testid="recently-viewed-empty">
      <Center>
        <Stack spacing="var(--zimm-scale-2xl)" textAlign="center" paddingY="var(--zimm-scale-4xl)">
          <Stack spacing="var(--zimm-scale-2xs)">
            <Text textStyle="heading2" color="var(--zimm-color-text-default)">
              {intl.formatMessage(messages.emptyHeading)}
            </Text>
            <Text textStyle="body1" color="var(--zimm-color-text-secondary)">
              {isRegistered
                ? intl.formatMessage(messages.emptyBodyRegistered)
                : intl.formatMessage(messages.emptyBodyGuest)}
            </Text>
          </Stack>
          <Stack direction={{ base: 'column', sm: 'row' }} justify="center" spacing="var(--zimm-scale-m)">
            {/* Continue Shopping is the loud/primary CTA for a registered shopper (their only
                CTA), but yields primary emphasis to Sign In for a guest -- same isRegistered-driven
                emphasis flip EmptyCart's own solid/outline split encodes, re-expressed here via
                ZimmButton's own primary/secondary variants instead of a raw colour override. */}
            <Button
              as={Link}
              href="/"
              variant={isRegistered ? 'primary' : 'secondary'}
              width={{ base: 'full', sm: 'auto' }}
            >
              {intl.formatMessage(messages.continueShopping)}
            </Button>
            {!isRegistered && (
              <Button as={Link} href="/account" variant="primary" width={{ base: 'full', sm: 'auto' }}>
                {intl.formatMessage(messages.signIn)}
              </Button>
            )}
          </Stack>
        </Stack>
      </Center>
    </Box>
  );
};

/**
 * SFCC-84 -- Recently Viewed Full History page container (build plan §B2, rewired to real Einstein
 * data by build plan step E2). Thin container: calls `useEinstein()` directly, fires
 * `getRecommendations(EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED)` once on mount, reads
 * `recommendations.recs` off that same hook once the request resolves, maps each rec through the
 * unchanged `selectRecentlyViewedFullHistoryCard` (filtering the hard `null` gate every mapper in
 * this codebase uses), and renders `ZimmRecentlyViewedGrid` -- or, with no recs, this page's own
 * empty state (`EmptyRecentlyViewed` above). Matches `recommended-products/index.tsx`'s own
 * Recently-Viewed branch exactly (build plan step E1, already committed) -- same
 * `useEinstein()`/`getRecommendations`/`recommendations.recs` chain, same unmodified mapper family,
 * just this page's own container instead of that shared rail.
 *
 * **Replaces the interim, browser-tracked view-history hook and its companion product-fetch
 * utility this page previously shipped with** (both deleted in build plan step E4; see
 * `recommended-products/index.tsx`'s own module docblock, which names them directly, for the full
 * "why" of that interim build and why it is superseded now). `recommendations.recs` is a strict
 * superset of the plain `ShopperProductsTypes.Product` shape the interim build fed this same
 * mapper (Einstein's own `fetchRecProductDetails`, `use-einstein.js:465-520`, already merges each
 * rec with its full hydrated `getProducts` record before this component ever sees it), so
 * `selectRecentlyViewedFullHistoryCard` needed no change at all -- confirmed directly against that
 * function's body, not assumed.
 *
 * **Known, already-flagged gap, not introduced here:** `selectRecentlyViewedFullHistoryCard`'s
 * `badge` field is always `undefined` -- the plain `getProducts` endpoint this build reads from has
 * no confirmed `c_productBadges` field (see that mapper's own docblock's "Badge" section). A card
 * rendered by this page will never show a badge yet; this is a pre-existing, out-of-scope gap for
 * this step, not a bug in this file.
 *
 * **Empty-state gate, race-safe (build plan step E2, decision #3):** `recs.length > 0` renders the
 * grid; `!isLoading && recs.length === 0` renders `EmptyRecentlyViewed`; anything else (i.e.
 * `isLoading` still `true`, request in flight, no recs yet) renders neither -- the same principle
 * `recommended-products/index.tsx`'s own `!recommendations?.recs?.length` gate already applies
 * (build plan step E1), just split into two named branches here because this page, unlike that
 * rail, has a real, visible empty-state component that must not flash for a shopper who does have
 * history. Gating on `cards.length === 0` (the post-mapping, filtered count) instead of
 * `recs.length` (the raw Einstein count) would risk exactly that flash while
 * `selectRecentlyViewedFullHistoryCard` is still filtering what could still turn out to be a
 * fully-populated `recs` array -- gating on `recs.length` directly, ahead of that mapping step,
 * avoids it. The one residual case this still can't distinguish from a genuine empty history --
 * every returned rec failing to map (e.g. every product now offline/deleted) -- is the same
 * accepted edge case the pre-revision hook-based gate already carried: `ZimmRecentlyViewedGrid`
 * renders `null` for an empty `cards` array by its own documented contract, so that narrow case
 * renders blank content rather than either this page's populated grid or its own empty-state copy.
 * Not solved here, not new here.
 *
 * **First-paint window, inherited from `useEinstein()` itself, not new here:** `isLoading` and
 * `recommendations` both start at `false`/`[]` (`use-einstein.js:462-463`) on every render,
 * including the server-rendered one and this component's very first client render, before the
 * mount effect below has had any chance to run -- so, same as the pre-revision hook-based design
 * this replaces (that hook's own `useState` initial values were equally empty on first render),
 * there is a real window on first paint where this gate reads "not loading, zero recs" and renders
 * `EmptyRecentlyViewed`, until the effect fires and flips `isLoading` to `true`. Unlike the
 * pre-revision design, that fix-up was a synchronous `Storage` read (imperceptible); this one is a
 * real network round-trip (`getRecommendations` -> Einstein -> `getProducts` hydration), so the
 * window is not instant -- named here rather than left as a silent, undocumented regression. This
 * is a property of `useEinstein()`'s own initial state, not something this container introduces or
 * can resolve without changing that base SFCC hook (out of scope for this step).
 *
 * **SEO -- `noindex, nofollow`, via `Seo`'s `children`, not its `noIndex` prop.** Base `Seo`
 * (`node_modules/@salesforce/retail-react-app/app/components/seo/index.jsx:20`) emits
 * `<meta name="robots" content="noindex" />` for `noIndex` -- `noindex` only, never `nofollow`.
 * Passing both `noIndex` and an explicit `<meta name="robots">` child would emit two competing
 * `robots` tags, so `noIndex` is left unset and the full directive is passed as a child instead
 * (Marcel's explicit decision, build plan §B2). `<Seo>` is otherwise mounted exactly as
 * `home/index.tsx` mounts it -- `title`/`description` only, no extra props.
 *
 * `getTemplateName` matches the convention already used by every other page-level override
 * (`home`, `product-detail`, `product-list`, `experience`, `contentful-preview` -- see each file's
 * own `<Page>.getTemplateName = () => '<name>';` line, placed the same way here).
 */
const RecentlyViewed = () => {
  const intl = useIntl();
  const { isRegistered } = useCustomerType();
  const { isLoading, recommendations, getRecommendations } = useEinstein();
  const toast = useToast();
  const { addItemToNewOrExistingBasket } = useShopperBasketsMutationHelper();

  // Fires once on mount -- matches recommended-products/index.tsx's own Recently-Viewed branch
  // (build plan step E1), which fires the identical call for the identical recommender, just from
  // an effect with a wider dependency array (that component also handles other recommenders/zones
  // sharing one effect). This page only ever renders this one recommender, so an empty dependency
  // array is the direct equivalent -- `react-hooks/exhaustive-deps` is off repo-wide
  // (@salesforce/pwa-kit-dev/configs/eslint/partials/react.js:26), and this exact
  // fire-once-on-mount-with-no-deps pattern already has a precedent needing no lint suppression:
  // home/index.tsx's own `useEffect(() => { einstein.sendViewPage(pathname); }, []);`.
  useEffect(() => {
    getRecommendations(EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED);
  }, []);

  // Same split product-list/productListCardMapper.ts's and recommended-products/index.tsx's own
  // consumers already use: formatPrice is injected into the mapper rather than formatted inside
  // it, keeping that mapper free of any react-intl dependency of its own.
  const formatPrice = (amount: number, currency: string): string =>
    intl.formatNumber(amount, { style: 'currency', currency });

  // Size-aware Add to Bag (2026-09-09 full-parity-with-PLP build) -- keyed by product id rather
  // than product-list/index.tsx's own per-card `ProductListCard` wrapper with local `useState`:
  // that pattern needs a per-card component instance to own its own state, but this page's grid
  // (`ZimmRecentlyViewedGrid`) is a shared, already-shipped organism that renders `cards` directly
  // with no per-card wrapper slot of its own (unlike PLP, which builds its own grid inline with
  // full control) -- touching that organism's contract to add one would be a bigger, cross-cutting
  // change than this fix calls for (AGENTS.md Hard Rule #5: never refactor upward). A single
  // id-keyed map at this container achieves the same "each card remembers its own selected size"
  // result without touching the Grid at all.
  const [selectedSizeChipValues, setSelectedSizeChipValues] = useState<Record<string, string | undefined>>({});

  const handleResolvedAddToBag = (orderableProductId: string, price: number | undefined) => {
    addItemToNewOrExistingBasket([{ productId: orderableProductId, price, quantity: 1 }])
      .then(() => toast({ title: intl.formatMessage(messages.addedToBag), status: 'success' }))
      .catch(() => toast({ title: intl.formatMessage(API_ERROR_MESSAGE), status: 'error' }));
  };

  // Normalized to a real array so every `recs.length`/`recs.map` reference below is safe without
  // repeating the optional chain at each call site -- `useEinstein()`'s own `recommendations`
  // state starts as a plain `[]` (use-einstein.js:463), which has no `.recs` property at all, so
  // `recommendations?.recs` reads `undefined` until the request above resolves.
  const recs: RecentlyViewedFullHistoryProduct[] = recommendations?.recs ?? [];

  const cards: ZimmProductCardProps[] = recs
    .map((product): RecentlyViewedFullHistoryCard | null => {
      const card = selectRecentlyViewedFullHistoryCard(product, formatPrice);
      if (!card) return null;

      const selectedSizeChipValue = selectedSizeChipValues[product.id];
      return {
        ...card,
        selectedSizeChipValue,
        onSizeChipSelect: (value: string) =>
          setSelectedSizeChipValues((previous) => ({ ...previous, [product.id]: value })),
        onAddToBag: () => {
          // No selection -> default-variant behaviour (matches product-list/index.tsx's own
          // ProductListCard.handleAddToBag exactly): no size selected means default size. A
          // selection that somehow matches no real variant falls back the same way, rather than
          // blocking the add entirely on a data mismatch.
          const resolved = selectedSizeChipValue ? resolveOrderableVariant(product, selectedSizeChipValue) : null;
          handleResolvedAddToBag(resolved?.productId ?? product.id, resolved?.price ?? product.price);
        },
      };
    })
    .filter((card): card is RecentlyViewedFullHistoryCard => card !== null);

  const title = intl.formatMessage(messages.title);

  return (
    <Box data-testid="recently-viewed-page">
      <Seo title={title} description={PAGE_DESCRIPTION}>
        <meta name="robots" content="noindex, nofollow" />
      </Seo>
      {/* Screen-reader-only page heading — 2026-09-10, closing a real gap: this page had no
       * Heading element at all in either branch below, breaking the pattern product-list/index.tsx
       * and product-detail/index.tsx both already follow, and leaving up to
       * RECENTLY_VIEWED_HISTORY_MAX_STORED real <h3> product-name headings (ZimmRecentlyViewedGrid)
       * with nothing above them in the heading hierarchy (WCAG 2.2 AA 1.3.1/2.4.6). `srOnly`,
       * matching product-detail/index.tsx's own <h1> exactly — the page's own visible title
       * styling (ZimmRecentlyViewedGrid's own textStyle="heading3" span, unchanged here) is a
       * separate, wider pre-existing pattern (several other organisms do the same thing) and out
       * of scope for this fix. */}
      <Heading as="h1" srOnly>
        {title}
      </Heading>
      {recs.length > 0 ? (
        // Bleeds the grid edge-to-edge past #app-main's own sitewide padding, matching the
        // Recently Viewed Rail's own flush treatment (product-detail/product-list's
        // <RecommendedProducts mx={PAGE_CONTENT_BLEED_MX}>) — confirmed against this page's own
        // three real Figma frames (9551:78221 Desktop / 9560:137688 Tablet / 9560:138459 Mobile,
        // Zimmermann_Designs file), which show the header and every Product Card Group spanning
        // the full frame width, not inset within a page margin. ZimmRecentlyViewedGrid itself has
        // no passthrough/mx slot (unlike RecommendedProducts, which forwards `{...props}` to its
        // own wrapping Box for exactly this reason), so the bleed is applied here at the page
        // level instead. EmptyRecentlyViewed below is a distinct, centred layout with no
        // edge-to-edge requirement of its own — deliberately not wrapped the same way.
        //
        // APP_MAIN_BLEED_MX, not PAGE_CONTENT_BLEED_MX — corrected 2026-09-10 (real, live-confirmed
        // bug: this page rendered wider than the viewport at every breakpoint, e.g. 1504px at a
        // 1440px Desktop viewport). This page has no PageContainer/layerStyle="page" second
        // containment layer the way PDP/PLP do — #app-main's own padding is the only thing here to
        // cancel — so it needs the single-layer constant, not the two-layer one. See that
        // constant's own comment in app/constants/index.ts for the full root-cause math.
        <Box
          mx={APP_MAIN_BLEED_MX}
          // Space before the global Footer — Figma's own page frames (see the mx comment above
          // for the node ids) show this filled by "Footer Primary" (node 9560:110769 on Desktop,
          // same shape on Tablet/Mobile — a "Load More" button, deferred: real, Figma-annotated
          // functional requirement, not built yet, Marcel 2026-09-10), uniformly 32px top-padding +
          // 52px button + 80px bottom-padding = 164px on all three breakpoints, sitting flush
          // against both the last card row above it and the real Footer below it (zero extra gap
          // either side, confirmed directly). With no button to render, only the padding portion
          // is reserved here (32+80=112px, Marcel's own call, 2026-09-10) — not the button's own
          // 52px, since there's nothing occupying that height right now. This will need to grow by
          // that 52px once Load More is actually built; that future component replaces this
          // padding entirely rather than sitting alongside it.
          paddingBottom="calc(var(--zimm-scale-800) + var(--zimm-scale-5xl))" // 32px + 80px = 112px
        >
          <ZimmRecentlyViewedGrid
            title={title}
            itemCountLabel={intl.formatMessage(messages.itemCount, { count: cards.length })}
            cards={cards}
          />
        </Box>
      ) : !isLoading && recs.length === 0 ? (
        <EmptyRecentlyViewed isRegistered={isRegistered} />
      ) : null}
    </Box>
  );
};

RecentlyViewed.getTemplateName = () => 'recently-viewed';

export default RecentlyViewed;

