describe('RecentlyViewed — size-aware Add to Bag (2026-09-09, full parity with product-list/index.tsx)', () => {
  const buildCard = (id: string, name: string) => ({
    id,
    href: `/product/${id}`,
    name,
    headingLevel: 'h3' as const,
    primaryImage: { src: 'https://example.test/image.jpg', alt: name },
    variation: 'plp' as const,
  });

  test("with no size selected, adds the product's own default id/price and never calls resolveOrderableVariant", () => {
    const addItemToNewOrExistingBasket = vi.fn().mockResolvedValue(undefined);
    mockEinsteinReturn(false, [{ ...mockProducts[0], price: 250 }]);
    mockSelectRecentlyViewedFullHistoryCard.mockReturnValue(buildCard('rv-1', 'Product One'));

    renderPage(true, addItemToNewOrExistingBasket);

    const gridProps = mockZimmRecentlyViewedGrid.mock.calls[0][0];
    act(() => {
      asPlpCard(gridProps.cards[0]).onAddToBag?.();
    });

    expect(mockResolveOrderableVariant).not.toHaveBeenCalled();
    expect(addItemToNewOrExistingBasket).toHaveBeenCalledWith([{ productId: 'rv-1', price: 250, quantity: 1 }]);
  });

  test('selecting a size chip then adding to bag resolves the real orderable variant for that card only', () => {
    const addItemToNewOrExistingBasket = vi.fn().mockResolvedValue(undefined);
    mockEinsteinReturn(false, mockProducts);
    mockSelectRecentlyViewedFullHistoryCard.mockImplementation((product) =>
      buildCard(product?.id ?? '', product?.name ?? ''),
    );
    mockResolveOrderableVariant.mockImplementation((product, sizeValue) =>
      product.id === 'rv-1' && sizeValue === 'xs' ? { productId: 'rv-1-XS', price: 300, orderable: true } : null,
    );

    renderPage(true, addItemToNewOrExistingBasket);

    // Selecting a size chip is a state update outside a real DOM event -- act() flushes it so the
    // next render's props (captured below, not the stale first-render snapshot) reflect it.
    act(() => {
      asPlpCard(mockZimmRecentlyViewedGrid.mock.calls[0][0].cards[0]).onSizeChipSelect?.('xs');
    });

    const latestCall = mockZimmRecentlyViewedGrid.mock.calls[mockZimmRecentlyViewedGrid.mock.calls.length - 1][0];
    // Only rv-1's card picked up the selection -- rv-2's own selectedSizeChipValue is untouched,
    // proving this is a per-card id-keyed map, not one shared piece of page-level state.
    expect(asPlpCard(latestCall.cards[0]).selectedSizeChipValue).toBe('xs');
    expect(asPlpCard(latestCall.cards[1]).selectedSizeChipValue).toBeUndefined();

    act(() => {
      asPlpCard(latestCall.cards[0]).onAddToBag?.();
    });

    expect(mockResolveOrderableVariant).toHaveBeenCalledWith(mockProducts[0], 'xs');
    expect(addItemToNewOrExistingBasket).toHaveBeenCalledWith([{ productId: 'rv-1-XS', price: 300, quantity: 1 }]);
  });

  test("a selection matching no real variant falls back to the product's own default id/price, same as no selection at all", () => {
    const addItemToNewOrExistingBasket = vi.fn().mockResolvedValue(undefined);
    mockEinsteinReturn(false, [{ ...mockProducts[0], price: 250 }]);
    mockSelectRecentlyViewedFullHistoryCard.mockReturnValue(buildCard('rv-1', 'Product One'));
    mockResolveOrderableVariant.mockReturnValue(null);

    renderPage(true, addItemToNewOrExistingBasket);

    act(() => {
      asPlpCard(mockZimmRecentlyViewedGrid.mock.calls[0][0].cards[0]).onSizeChipSelect?.('no-such-size');
    });
    const latestCall = mockZimmRecentlyViewedGrid.mock.calls[mockZimmRecentlyViewedGrid.mock.calls.length - 1][0];
    act(() => {
      asPlpCard(latestCall.cards[0]).onAddToBag?.();
    });

    expect(addItemToNewOrExistingBasket).toHaveBeenCalledWith([{ productId: 'rv-1', price: 250, quantity: 1 }]);
  });
});

